import time
from typing import Any, Dict, Optional, Tuple


class TTLCache:
    def __init__(self) -> None:
        self._data: Dict[Any, Tuple[Any, float]] = {}

    def get(self, key: Any) -> Optional[Any]:
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if time.monotonic() >= expires_at:
            del self._data[key]
            return None
        return value

    def set(self, key: Any, value: Any, ttl: float) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be > 0 seconds")
        self._data[key] = (value, time.monotonic() + ttl)

    def delete(self, key: Any) -> bool:
        return self._data.pop(key, None) is not None

    def clear(self) -> None:
        self._data.clear()

    def cleanup(self) -> int:
        now = time.monotonic()
        expired = [k for k, (_, exp) in self._data.items() if now >= exp]
        for k in expired:
            del self._data[k]
        return len(expired)

    def __len__(self) -> int:
        return len(self._data)
```

Usage:

```python
cache = TTLCache()
cache.set("user:1", {"name": "Ada"}, ttl=5.0)

print(cache.get("user:1"))   # {'name': 'Ada'}
time.sleep(6)
print(cache.get("user:1"))   # None
```

Behavior: entries expire lazily. `get` checks the timestamp and removes the entry if it is expired; `set` overwrites any existing key and resets its TTL. `cleanup()` is optional and removes expired entries eagerly.

Complexity: average `O(1)` time for `get`, `set`, and `delete`; `O(n)` space for `n` live entries; `cleanup()` is `O(n)`. `time.monotonic()` is used so wall-clock changes do not affect expiration. This is not thread-safe by default; add a lock if used across threads.
